#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int num, age; char name[32], sex; struct Node *next; } Node;

int main(void) {
    int n, age;
    Node *head = NULL, **tail = &head;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        Node *node = malloc(sizeof(*node));
        if (!node) return 1;
        scanf("%d%31s %c%d", &node->num, node->name, &node->sex, &node->age);
        node->next = NULL; *tail = node; tail = &node->next;
    }
    scanf("%d", &age);
    Node **link = &head;
    while (*link) {
        if ((*link)->age == age) { Node *old = *link; *link = old->next; free(old); }
        else link = &(*link)->next;
    }
    if (!head) puts("EMPTY");
    while (head) {
        printf("%d %s %c %d\n", head->num, head->name, head->sex, head->age);
        Node *next = head->next; free(head); head = next;
    }
    return 0;
}
